101	// ─── TryFrom<JsExtractOptions> for PipelineOptions ────────────────────────────
102	
103	impl TryFrom<JsExtractOptions> for PipelineOptions {
104	    /// Names the bad `reactVersion` value — a typo (or a caller bypassing the
105	    /// `'react18' | 'react19'` TS type, e.g. via `as any`) must not silently
106	    /// fall back to react19 (CLAUDE.md non-negotiable #6).
107	    type Error = String;
108	
109	    fn try_from(js: JsExtractOptions) -> Result<Self, Self::Error> {
110	        use compact_str::CompactString;
111	
112	        let mut opts =
113	            PipelineOptions { src_dirs: js.src_dirs.into_iter().map(Into::into).collect(), ..Default::default() };
114	
115	        if let Some(exclude) = js.exclude {
116	            opts.exclude_patterns = exclude;
117	        }
118	        if let Some(v) = js.react_version.as_deref() {
119	            opts.react_version = oxc_react_docgen_core::react_types::parse_react_version(v)
120	                .map_err(|bad| format!("reactVersion is '{bad}', expected \"react18\" or \"react19\""))?;
121	        }
122	        if let Some(cross_package) = js.cross_package {
123	            opts.cross_package = cross_package;
124	        }
125	        if let Some(dir) = js.pandacss_outdir {
126	            opts.pandacss_outdir = Some(dir.into());
127	        }
128	        if let Some(fns) = js.variant_functions {
129	            opts.variant_functions = fns;
130	        }
131	        if let Some(mode) = js.html_attributes.as_deref() {
132	            opts.html_attributes = match mode {
133	                "full" => oxc_react_docgen_core::pipeline::HtmlAttributeMode::Full,
134	                "none" => oxc_react_docgen_core::pipeline::HtmlAttributeMode::None,
135	                _ => oxc_react_docgen_core::pipeline::HtmlAttributeMode::Curated,
136	            };
137	        }
138	        if let Some(path) = js.tsconfig_path {
139	            opts.tsconfig_path = Some(path.into());
140	        }
141	        if let Some(names) = js.extra_builtins {
142	            opts.extra_builtins = names.into_iter().map(CompactString::from).collect();
143	        }
144	        if let Some(json) = js.extra_paths_json {
145	            opts.extra_paths = serde_json::from_str(&json).map_err(|e| format!("extraPaths is not valid JSON: {e}"))?;
146	        }
147	        if let Some(json) = js.known_type_overrides_json {
148	            opts.known_type_overrides =
149	                serde_json::from_str(&json).map_err(|e| format!("knownTypeOverrides is not valid JSON: {e}"))?;
150	        }
151	        if let Some(v) = js.vanilla_extract {
152	            opts.vanilla_extract = v;
153	        }
154	        if let Some(dir) = js.cache_dir {
155	            opts.cache_dir = Some(dir.into());
156	        }
157	        if let Some(v) = js.resolve_complex_types {
158	            opts.resolve_complex_types = v;
159	        }
160	
161	        Ok(opts)
162	    }
163	}
