294	/// Release session state. Call in Vite's buildEnd hook.
295	#[napi]
296	pub fn close_session(session_id: u32) {
297	    let _ = oxc_react_docgen_core::panic_guard::contain_panic("close_session", move || {
298	        #[cfg(test)]
299	        if session_id == CLOSE_SESSION_PANIC_TEST_SENTINEL {
300	            panic!("simulated close_session panic (test-only sentinel)");
301	        }
302	
303	        SESSIONS.remove(&session_id);
304	    });
305	}
