16	/// Resolve a named type to a chain of props.
17	/// This is the recursive core — handles interfaces, aliases, known patterns, etc.
18	#[allow(clippy::too_many_arguments)]
19	pub(super) fn resolve_props_chain(
20	    type_name: &str,
21	    type_args: &[String],
22	    consuming_file: &Utf8Path,
23	    mapping: &ComponentMapping,
24	    ctx: &ResolutionContext,
25	    state: &mut ResolveState,
26	    depth: u8,
27	) -> ResolvedChain {
28	    if depth > MAX_DEPTH {
29	        let diag = super::max_depth_diagnostic(&format!("type '{}'", type_name), consuming_file);
30	        return ResolvedChain::give_up(type_name.to_owned(), Some(diag), state);
31	    }
32	
33	    // Cycle detection — scoped by file so same type name in different files is OK.
34	    // Must include type_args: distinct instantiations of the same generic alias
35	    // (e.g. `Partial<RowHeights>` vs `Partial<ColumnWidths>` in the same interface's
36	    // extends list) are not the same visit and must not collide on the bare name alone.
37	    let visit_key: CompactString = format!("{}:{}<{}>", consuming_file, type_name, type_args.join(",")).into();
38	    if !state.visited.insert(visit_key) {
39	        return ResolvedChain::give_up(
40	            type_name.to_owned(),
41	            Some(Diagnostic {
42	                severity: DiagnosticSeverity::Info,
43	                message: format!(
44	                    "Circular type reference detected resolving '{}' in '{}' — stopping here to avoid infinite recursion",
45	                    type_name, consuming_file
46	                ),
47	                file: Some(consuming_file.to_string()),
48	                line: None,
49	                column: None,
50	                help: Some("This type (directly or indirectly) extends or references itself.".into()),
51	                code: DiagnosticCode::MaxDepthExceeded,
52	            }),
53	            state,
54	        );
55	    }
56	
57	    // Strip "React." namespace prefix before all builtin/utility checks.
58	    let type_name_bare = type_name.strip_prefix("React.").unwrap_or(type_name);
59	
60	    // ── Step 0.5: Inline utility type in extends position ─────────────────────
61	    // Pick/Omit/Partial/Readonly appearing directly in `extends Pick<T,K>`
62	    // have non-empty type_args. Route through alias resolver (same logic as
63	    // `type X = Pick<T,K>`) instead of the step-1 silent no-op.
64	    if !type_args.is_empty() {
65	        let synthetic = match type_name_bare {
66	            // Guard: skip if the base type is itself generic (contains '<').
67	            // Raw string type_args can't represent nested generics reliably.
68	            "Pick" if type_args.len() >= 2 && !type_args[0].contains('<') => {
69	                let base = CollectedType::Named { name: type_args[0].as_str().into(), args: vec![] };
70	                Some(CollectedTypeAlias::Pick {
71	                    base,
72	                    picked_keys: parse_string_union_keys(&type_args[1]),
73	                    file_path: consuming_file.to_owned(),
74	                })
75	            }
76	            "Omit" if type_args.len() >= 2 && !type_args[0].contains('<') => {
77	                let base = CollectedType::Named { name: type_args[0].as_str().into(), args: vec![] };
78	                Some(CollectedTypeAlias::Omit {
79	                    base,
80	                    omitted_keys: parse_string_union_keys(&type_args[1]),
81	                    omitted_keys_of: None,
82	                    file_path: consuming_file.to_owned(),
83	                })
84	            }
85	            "Partial" if !type_args.is_empty() && !type_args[0].contains('<') => {
86	                let base = CollectedType::Named { name: type_args[0].as_str().into(), args: vec![] };
87	                Some(CollectedTypeAlias::Partial { base, file_path: consuming_file.to_owned() })
88	            }
89	            "Readonly" if !type_args.is_empty() && !type_args[0].contains('<') => {
90	                let base = CollectedType::Named { name: type_args[0].as_str().into(), args: vec![] };
91	                Some(CollectedTypeAlias::Passthrough { target: base, file_path: consuming_file.to_owned() })
92	            }
93	            _ => None,
94	        };
95	        if let Some(alias) = synthetic {
96	            return resolve_type_alias_chain(&alias, consuming_file, mapping, ctx, state, depth);
97	        }
98	    }
99	
100	    // ── Step 1: TypeScript built-in utility types — silent no-op ─────────────
101	    // Not prop providers; suppress false "unresolvable" warnings.
102	    if super::is_ts_utility_type(type_name_bare) {
103	        return ResolvedChain::empty();
104	    }
105	
106	    // ── Step 2: Try the project's own source before a known-pattern shortcut ─
107	    // See `resolver::precedence` — the shared, single-source-of-truth order
108	    // `named.rs` already used correctly; this path used to reimplement the
109	    // sequence independently and check known patterns first, silently
110	    // replacing project-defined types (e.g. a project's own `interface
111	    // SxProps`) with the hardcoded library shortcut. Fixed: P0-1.
112	    let resolved_args: Vec<PropType> = type_args
113	        .iter()
114	        .map(|a| {
115	            let ct = CollectedType::Raw(a.clone());
116	            resolve_collected_type(&ct, consuming_file, ctx, state, depth + 1)
117	        })
118	        .collect();
119	
120	    let (canonical_file, canonical_name, matched) =
121	        super::precedence::resolve_source_defined_or_known(type_name_bare, &resolved_args, consuming_file, ctx, state);
122	
123	    match matched {
124	        Some(super::precedence::SourceOrKnownMatch::TypeAlias { matched_key, alias }) => {
125	            let alias = super::substitute::apply_generic_args(
126	                alias,
127	                &matched_key,
128	                type_args,
129	                consuming_file,
130	                ctx,
131	                &mut state.diagnostics,
132	            );
133	            return resolve_type_alias_chain(&alias, consuming_file, mapping, ctx, state, depth);
134	        }
135	        Some(super::precedence::SourceOrKnownMatch::Interface(iface)) => {
136	            return resolve_interface_chain(iface, type_args, consuming_file, mapping, ctx, state, depth);
137	        }
138	        Some(super::precedence::SourceOrKnownMatch::Known(result)) => {
139	            return match result {
140	                KnownPatternResult::Props(props) => ResolvedChain { props, ..ResolvedChain::empty() },
141	                KnownPatternResult::Type(PropType::HtmlAttributes { element, omitted }) => {
142	                    let layer = InheritedLayer {
143	                        type_name: type_name.to_owned(),
144	                        file_name: resolve_react_types_file(consuming_file, ctx),
145	                        omitted,
146	                        html_element: Some(element),
147	                        total_props: 0,
148	                    };
149	                    ResolvedChain { inheritance: vec![layer], ..ResolvedChain::empty() }
150	                }
151	                KnownPatternResult::Type(pt) => {
152	                    if let PropType::Opaque(detail) = &pt {
153	                        push_known_opaque_diagnostic(
154	                            &mut state.diagnostics,
155	                            detail.reason(),
156	                            type_name_bare,
157	                            consuming_file,
158	                        );
159	                    }
160	                    ResolvedChain::empty_with_compose(pt.raw_string())
161	                }
162	                KnownPatternResult::Alias { name } => {
163	                    resolve_props_chain(&name, &[], consuming_file, mapping, ctx, state, depth + 1)
164	                }
165	            };
166	        }
167	        None => {}
168	    }
169	
170	    // ── Step 2.5: React builtin check (after source and known patterns) ──────
171	    // Terminal React types (ReactNode, Ref, FC, etc.) that survived both are not
172	    // prop providers — add to composes and stop.
173	    if react_types::is_react_builtin(type_name_bare, &ctx.extra_builtins) {
174	        return ResolvedChain::empty_with_compose(type_name.to_owned());
175	    }
176	
177	    // ── Step 6: Unresolvable ──────────────────────────────────────────────────
178	    // Import resolution may have redirected `type_name` to a different name/file
179	    // (re-exports, barrel files) — surface that resolved location when it differs,
180	    // since "Cannot resolve X in file A" is confusing if X actually lives in file B.
181	    let location_note = super::unresolved_location_note(type_name, consuming_file, &canonical_file, &canonical_name);
182	    state.diagnostics.push(Diagnostic {
183	        severity: DiagnosticSeverity::Warning,
184	        message: format!("Cannot resolve type '{}' in '{}'{}", type_name, consuming_file, location_note),
185	        file: Some(consuming_file.to_string()),
186	        line: None,
187	        column: None,
188	        help: Some(
189	            "Type may be in an unresolvable cross-package location. Check that the package is installed.".into(),
190	        ),
191	        code: DiagnosticCode::UnresolvableImport,
192	    });
193	    ResolvedChain::empty_with_compose(type_name.to_owned())
194	}
