196	/// Resolve an interface to a chain of props.
197	#[allow(clippy::too_many_arguments)]
198	pub(super) fn resolve_interface_chain(
199	    iface: &CollectedInterface,
200	    _type_args: &[String],
201	    _consuming_file: &Utf8Path,
202	    mapping: &ComponentMapping,
203	    ctx: &ResolutionContext,
204	    state: &mut ResolveState,
205	    depth: u8,
206	) -> ResolvedChain {
207	    let mut chain = ResolvedChain::empty();
208	
209	    // A generic interface's own declared type parameters (`interface Foo<TData>`)
210	    // are expected, unexpandable placeholders wherever referenced in its body —
211	    // not unresolvable types. Register them so `resolve_named` doesn't warn.
212	    if let Some(params) = ctx.global.interface_type_params.get(&iface.scoped_key) {
213	        state.in_scope_type_params.extend(params.iter().cloned());
214	    }
215	
216	    // ── Resolve extends first — parent props come before own props ────────────
217	    for extends_ref in &iface.extends {
218	        let (parent_chain, maybe_layer) =
219	            resolve_extends_ref(extends_ref, &iface.file_path, mapping, ctx, state, depth + 1);
220	        if let Some(layer) = maybe_layer {
221	            chain.inheritance.push(layer);
222	        }
223	        chain.merge_parent(parent_chain);
224	    }
225	
226	    // ── Resolve own props ────────────────────────────────────────────────────
227	    let parent = PropParent { name: iface.name.to_string(), file_name: iface.file_path.to_string() };
228	
229	    for raw_prop in &iface.props {
230	        let prop_type = resolve_collected_type(&raw_prop.collected_type, &iface.file_path, ctx, state, depth);
231	
232	        // Default value: code default takes precedence over JSDoc @default.
233	        let code_default = mapping.param_defaults.get(&raw_prop.name);
234	        let jsdoc_default =
235	            raw_prop.tags.get("default").or_else(|| raw_prop.tags.get("defaultValue")).map(|s| s.trim());
236	
237	        let default_value = match (code_default, jsdoc_default) {
238	            (Some(code), Some(jsdoc))
239	                if code.value.trim_matches('"').trim_matches('\'') != jsdoc.trim_matches('"').trim_matches('\'') =>
240	            {
241	                state.diagnostics.push(Diagnostic {
242	                    severity: DiagnosticSeverity::Info,
243	                    message: format!(
244	                        "JSDoc @default '{}' differs from code default '{}' for prop '{}' — using code value",
245	                        jsdoc, code.value, raw_prop.name
246	                    ),
247	                    file: Some(iface.file_path.to_string()),
248	                    line: None,
249	                    column: None,
250	                    help: Some("Update the JSDoc @default to match the code default.".into()),
251	                    code: DiagnosticCode::JsDocDefaultMismatch,
252	                });
253	                Some(DefaultValue { value: code.value.clone(), computed: code.computed })
254	            }
255	            (Some(code), _) => Some(DefaultValue { value: code.value.clone(), computed: code.computed }),
256	            (None, Some(jsdoc)) => Some(DefaultValue { value: jsdoc.to_owned(), computed: false }),
257	            (None, None) => None,
258	        };
259	
260	        chain.props.push(ParsedProp::new(
261	            raw_prop.name.clone(),
262	            prop_type,
263	            raw_prop.required,
264	            default_value,
265	            raw_prop.description.clone(),
266	            raw_prop.tags.clone(),
267	            Some(parent.clone()),
268	            vec![parent.clone()],
269	        ));
270	    }
271	
272	    chain
273	}
