275	/// Find a discriminant prop — a prop that has a distinct string literal type across all members.
276	pub(super) fn find_discriminant_prop(members: &[(&str, Vec<ParsedProp>)]) -> Option<String> {
277	    if members.is_empty() {
278	        return None;
279	    }
280	
281	    // Collect candidate prop names: appear in all members AND have PropType::StringLiteral in at least one.
282	    // Use the intersection of all member prop names as candidates.
283	    let mut candidate_names: Option<std::collections::BTreeSet<&str>> = None;
284	    for (_, member_props) in members {
285	        let names: std::collections::BTreeSet<&str> = member_props.iter().map(|p| p.name.as_str()).collect();
286	        candidate_names = Some(match candidate_names {
287	            None => names,
288	            Some(existing) => existing.intersection(&names).copied().collect(),
289	        });
290	    }
291	    let candidate_names = candidate_names.unwrap_or_default();
292	
293	    'outer: for candidate in &candidate_names {
294	        // Check that this prop has a string literal type in at least one member.
295	        let has_literal = members.iter().any(|(_, props)| {
296	            props.iter().any(|p| p.name.as_str() == *candidate && matches!(p.prop_type, PropType::StringLiteral(_)))
297	        });
298	        if !has_literal {
299	            continue;
300	        }
301	
302	        let mut literal_values: Vec<&str> = Vec::new();
303	        for (_, member_props) in members {
304	            let found = member_props.iter().find(|p| p.name.as_str() == *candidate);
305	            match found {
306	                Some(p) => {
307	                    if let PropType::StringLiteral(ref s) = p.prop_type {
308	                        if literal_values.contains(&s.as_str()) {
309	                            // Not distinct — try next prop.
310	                            continue 'outer;
311	                        }
312	                        literal_values.push(s.as_str());
313	                    } else {
314	                        continue 'outer; // Not a literal in this member.
315	                    }
316	                }
317	                None => continue 'outer, // Not present in all members.
318	            }
319	        }
320	
321	        if literal_values.len() == members.len() {
322	            return Some((*candidate).to_owned());
323	        }
324	    }
325	
326	    None
327	}
