329	/// Parse a TypeScript string union like `'disabled' | 'type' | 'form'` into individual key strings.
330	fn parse_string_union_keys(raw: &str) -> Vec<String> {
331	    raw.split('|').map(|s| s.trim().trim_matches('\'').trim_matches('"').to_owned()).filter(|s| !s.is_empty()).collect()
332	}
