77	pub fn cmd_lsp() -> Result<()> {
78	    let stdin = io::stdin();
79	    let mut stdin_lock = stdin.lock();
80	    let stdout = io::stdout();
81	    let mut stdout_lock = stdout.lock();
82	
83	    loop {
84	        let content_length = match read_content_length(&mut stdin_lock) {
85	            Err(()) => return Ok(()), // EOF
86	            Ok(v) => v,
87	        };
88	
89	        let Some(len) = content_length else {
90	            tracing::error!(
91	                "LSP frame's header block had no usable Content-Length; closing connection to avoid a desynced stream"
92	            );
93	            return Err(miette::miette!("received an LSP frame without a usable Content-Length header"));
94	        };
95	
96	        check_content_length(len)?;
97	
98	        let mut buf = vec![0u8; len];
99	        if stdin_lock.read_exact(&mut buf).is_err() {
100	            return Ok(());
101	        }
102	
103	        let Ok(msg) = serde_json::from_slice::<serde_json::Value>(&buf) else {
104	            continue;
105	        };
106	
107	        if let Some(method) = msg["method"].as_str() {
108	            let id = msg.get("id");
109	            match method {
110	                "initialize" => {
111	                    if let Some(id) = id {
112	                        let response = serde_json::json!({
113	                            "jsonrpc": "2.0",
114	                            "id": id,
115	                            "result": initialize_result()
116	                        });
117	                        send_response(&mut stdout_lock, &response);
118	                    }
119	                }
120	                "shutdown" => {
121	                    if let Some(id) = id {
122	                        let response = serde_json::json!({
123	                            "jsonrpc": "2.0",
124	                            "id": id,
125	                            "result": null
126	                        });
127	                        send_response(&mut stdout_lock, &response);
128	                    }
129	                }
130	                "exit" => break,
131	                _ => {}
132	            }
133	        }
134	    }
135	
136	    Ok(())
137	}
138	
139	fn send_response<W: Write>(out: &mut W, response: &serde_json::Value) {
140	    if let Ok(json) = serde_json::to_string(response) {
141	        let header = format!("Content-Length: {}\r\n\r\n", json.len());
142	        let _ = out.write_all(header.as_bytes());
143	        let _ = out.write_all(json.as_bytes());
144	        let _ = out.flush();
145	    }
146	}

